  Lemma want_x_val : forall vals len cap,
    vals_ev vals 7 = Z_to_bv 64 len -> vals_ev vals 8 = Z_to_bv 64 cap ->
    edenot (ENV vals) want_x = Z_to_bv 64 (cap - len).
